wsl.exe -d Ubuntu-24.04 -- bash -lc 'cp /home/lzttttt/mubiao--test/contact_app.py /mnt/c/tmp/contact_app_v2_full.py'; $path='C:\tmp\contact_app_v2_full.py'; $text=(Get-Content -LiteralPath $path -Raw -Encoding UTF8).Replace("`r`n","`n"); function Replace-One([string]$old,[string]$new){if(-not $script:text.Contains($old)){throw "missing replacement: $($old.Substring(0,[Math]::Min(60,$old.Length)))"}; $script:text=$script:text.Replace($old,$new)}; Replace-One "from PIL import Image, ImageDraw`n`nfrom src import contact_annotations as contacts" "from PIL import Image, ImageDraw`n`nfrom src.bbox_editor import BBOX_EDITOR_CSS, BBOX_EDITOR_JS, render_bbox_editor`nfrom src import contact_annotations as contacts"; $editor=@'
def _editor_html(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
) -> str:
    index = int(state["index"])
    image = read_rgb(PROJECT_ROOT, bbox_records[index])
    display_size = _display_size(image)
    state["original_size"] = image.size
    state["display_size"] = display_size
    shown = image.resize(display_size, Image.Resampling.LANCZOS)
    existing = record_bbox(bbox_records[index])
    bbox_values = state.get("candidate_bbox") or (
        existing.as_list() if existing else None
    )
    contact = state.get("candidate_contact") or contacts.contact_point(
        contact_records[index]
    )
    return render_bbox_editor(
        shown,
        original_size=image.size,
        mode=str(state["mode"]),
        bbox=bbox_values,
        bbox_is_candidate=state.get("candidate_bbox") is not None,
        contact=contact,
        contact_is_candidate=state.get("candidate_contact") is not None,
    )
'@; Replace-One "def _progress(" ($editor+"`n`ndef _progress("); Replace-One "        _render(bbox_records, contact_records, state)," "        _editor_html(bbox_records, contact_records, state),"; $apply=@'
def _event_payload(evt: gr.EventData, name: str):
    data = getattr(evt, "_data", None)
    if isinstance(data, dict) and name in data:
        return data[name]
    return getattr(evt, name, None)


def on_editor_apply(state: dict[str, object], evt: gr.EventData):
    bbox_records = load_bbox_records(PROJECT_ROOT)
    contact_records = contacts.load_records(PROJECT_ROOT)
    state = dict(state)
    action = _event_payload(evt, "action")
    if action == "bbox":
        values = _event_payload(evt, "bbox")
        if not isinstance(values, (list, tuple)) or len(values) != 4:
            return _outputs(bbox_records, contact_records, state, "未收到有效的拖拽框坐标。")
        try:
            bbox = BBox(*values).normalized(*state["original_size"])
        except (TypeError, ValueError) as exc:
            return _outputs(bbox_records, contact_records, state, f"调整后的设备框无效：{exc}")
        state.update(first_corner=None, candidate_bbox=bbox.as_list())
        return _outputs(
            bbox_records,
            contact_records,
            state,
            "设备框已调整；确认边界后点击保存设备框。",
        )
    if action == "contact":
        values = _event_payload(evt, "point")
        if state.get("mode") != "contact":
            return _outputs(bbox_records, contact_records, state, "请先保存设备框。")
        if not isinstance(values, (list, tuple)) or len(values) != 2:
            return _outputs(bbox_records, contact_records, state, "未收到有效的接触点坐标。")
        width, height = state["original_size"]
        x = max(0, min(int(round(values[0])), width - 1))
        y = max(0, min(int(round(values[1])), height - 1))
        state["candidate_contact"] = [x, y]
        return _outputs(
            bbox_records,
            contact_records,
            state,
            f"已记录接触点 ({x}, {y})，确认后保存。",
